IT=F+'frmRptItemsSalesDetails.xaml.cs';IX=F+'frmRptItemsSalesDetails.xaml';IP=F+'frmRptItemsSalesDetailsPOS.xaml.cs';JX=F+'frmRptItemsSalesDetailsPOS.xaml'
