    illustration('A cancelled new dialog default is not selected identity','P7-091',dict(old_customer_id=7,new_dialog_int_default=0,selection_made=False),dict(update_customer_argument=0),dict(update_sent=False,customer_id=7),True,evidence((SA,1334,1430),(SC,19,43),(SC,266,293)))
