    illustration('Partial cash is not the invoice net','P7-092',dict(net=115,paid=40,stored_cash=40,pay_type=1,status='partial'),dict(reported_cash=115,reported_paid=40),dict(reported_cash=40,reported_paid=40),True,evidence((PO,425,435),(AN,491,501),(BI,532,560)))
