    illustration('Rows are supplied but explicit summary transfer is missing','P7-093',dict(rows=[100,20],required_signed_total=80),dict(rows_supplied=True,explicit_signed_summary_assignments=[],sdk_default='unknown-not-executed'),dict(rows_supplied=True,explicit_signed_summary_payload=80),True,evidence((PO,853,885),(AN,941,974),(RP,421,432)))
    illustration('Stored VAT criterion and displayed derived value can disagree','P7-094',dict(stored_FreeVATSales=0,derived_FreeVATSales=100,physical_column_present=True),dict(noVAT_predicate_member=False,withVAT_predicate_member=True,displayed_FreeVATSales=100),dict(same_derived_source_noVAT_member=True,same_derived_source_withVAT_member=False,displayed_FreeVATSales=100),True,evidence((AN,349,410),(AN,518,522),(RS,993,1000),(RS,48842,48844)))
    illustration('Matching persisted and derived values conceal the source split','P7-094',dict(stored_FreeVATSales=100,derived_FreeVATSales=100),dict(noVAT_member=True),dict(noVAT_member=True),False,evidence((AN,349,410)))
    movement=dict(sale=0,sale_return=0,pos=0,pos_return=0,purchase=3,purchase_return=0,purchase_amount=90)
    admitted=any(movement[k]!=0 for k in ('sale','sale_return','pos','pos_return'));assert not admitted
