    rows=[dict(deleted=False,amount=100),dict(deleted=True,amount=40)]
    illustration('Active-item test does not remove a deleted invoice','P7-067',dict(item_active=True,rows=rows),dict(amount=sum(x['amount'] for x in rows)),dict(amount=sum(x['amount'] for x in rows if not x['deleted'])),True,evidence((IP,180,211)))
    illustration('Raw unit-price line sum omits an independent discount','P7-083',dict(qty=1,unit_price=100,line_discount=10,tax=0,header_discount=0),dict(named_net=1*100),dict(net=1*100-10),True,evidence((IT,222,239),(IT,285,309),(IP,180,199)))
    def general_tax(tax,extra):
        main=tax-extra;vat=main if main>0 else tax
