    illustration('All checkbox can retain an old selected branch','P7-088',dict(authorized=['A','B'],branch_amounts={'A':100,'B':200},selected='A',all_checked=True),dict(query_branch='A',amount=100),dict(query_branch='authorized-A-and-B',amount=300),True,evidence((SA,342,345),(SA,781,785),(AN,289,292),(AN,680,684)))
    end=datetime(2026,1,1,23,59);late=datetime(2026,1,1,23,59,30);assert late>end
    illustration('A valid HH:mm end lacks the rest of that minute','P3-023',dict(valid_end_text='23:59',movement=late.isoformat(),fallback_used=False),dict(end=end.isoformat(),included=late<=end),dict(required_full_day_included=True,exclusive_end='2026-01-02T00:00:00'),True,evidence((SA,422,438),(SA,665,672),(IT,185,218)))
