    illustration('Mutable captions are not the criteria of an earlier result','P7-045',dict(loaded_period='A',loaded_rows=[100],controls_now='B',requery=False),dict(rows=[100],printed_period='B'),dict(rows=[100],printed_period='A',state='frozen-result-or-block-dirty-output'),True,evidence((SA,1465,1503),(IT,452,479),(IP,285,336)))
