    literal('WPF cards explicitly subtract returns','P7-093',[(SA,699,715),(PO,541,554),(AN,609,622)],lambda t:all('purchases.Sum(selector) - returns.Sum(selector)' in s and 'Calc(x => x.Net)' in s for s in t),'The three selected local summary-card folds are signed, unlike an unspecified ordinary grid summary. Not general financial certification.')
